=== FILE: axil_timer.v ===
// axil_timer: 32-bit down-counting timer with one-shot and periodic modes and
// a level interrupt, behind an AXI4-Lite subordinate port.
// Implements interface_spec.md per microarchitecture.md (task prj-97dea43f5b).
// Synchronous, active-low reset. Single clock.
module axil_timer #(
    parameter ADDR_WIDTH = 4
) (
    input  wire                  aclk,
    input  wire                  aresetn,
    input  wire [ADDR_WIDTH-1:0] s_axil_awaddr,
    input  wire                  s_axil_awvalid,
    output wire                  s_axil_awready,
    input  wire [31:0]           s_axil_wdata,
    input  wire [3:0]            s_axil_wstrb,
    input  wire                  s_axil_wvalid,
    output wire                  s_axil_wready,
    output reg  [1:0]            s_axil_bresp,
    output reg                   s_axil_bvalid,
    input  wire                  s_axil_bready,
    input  wire [ADDR_WIDTH-1:0] s_axil_araddr,
    input  wire                  s_axil_arvalid,
    output wire                  s_axil_arready,
    output reg  [31:0]           s_axil_rdata,
    output reg  [1:0]            s_axil_rresp,
    output reg                   s_axil_rvalid,
    input  wire                  s_axil_rready,
    output wire                  irq
);

  localparam [1:0] RESP_OKAY   = 2'b00;
  localparam [1:0] RESP_SLVERR = 2'b10;

  localparam [1:0] IDX_CTRL   = 2'd0;
  localparam [1:0] IDX_LOAD   = 2'd1;
  localparam [1:0] IDX_COUNT  = 2'd2;
  localparam [1:0] IDX_STATUS = 2'd3;

  // ---------------------------------------------------------------------
  // Channel state
  // ---------------------------------------------------------------------
  reg                  aw_held;
  reg                  w_held;
  reg [ADDR_WIDTH-1:0] aw_addr_q;
  reg [31:0]           w_data_q;
  reg [3:0]            w_strb_q;

  // ---------------------------------------------------------------------
  // Timer state
  // ---------------------------------------------------------------------
  reg        en;
  reg        ie;
  reg        mode;
  reg        expired;
  reg [31:0] load;
  reg [31:0] count;

  // ---------------------------------------------------------------------
  // Write path
  // ---------------------------------------------------------------------
  assign s_axil_awready = !aw_held && !s_axil_bvalid;
  assign s_axil_wready  = !w_held && !s_axil_bvalid;

  wire aw_hs = s_axil_awvalid && s_axil_awready;
  wire w_hs  = s_axil_wvalid && s_axil_wready;

  wire [ADDR_WIDTH-1:0] wr_addr = aw_held ? aw_addr_q : s_axil_awaddr;
  wire [31:0]           wr_data = w_held ? w_data_q : s_axil_wdata;
  wire [3:0]            wr_strb = w_held ? w_strb_q : s_axil_wstrb;

  wire do_write = (aw_held || aw_hs) && (w_held || w_hs);

  wire       wr_mapped = (wr_addr[1:0] == 2'b00) &&
                         ((wr_addr >> 4) == {ADDR_WIDTH{1'b0}});
  wire [1:0] wr_idx    = wr_addr[3:2];

  wire wr_ctrl  = do_write && wr_mapped && (wr_idx == IDX_CTRL) && wr_strb[0];
  wire wr_load  = do_write && wr_mapped && (wr_idx == IDX_LOAD);
  wire wr_clear = do_write && wr_mapped && (wr_idx == IDX_STATUS) &&
                  wr_strb[0] && wr_data[0];
  wire wr_okay  = wr_mapped && (wr_idx != IDX_COUNT);

  // ---------------------------------------------------------------------
  // Read path
  // ---------------------------------------------------------------------
  assign s_axil_arready = !s_axil_rvalid;

  wire ar_hs = s_axil_arvalid && s_axil_arready;

  wire rd_mapped = (s_axil_araddr[1:0] == 2'b00) &&
                   ((s_axil_araddr >> 4) == {ADDR_WIDTH{1'b0}});

  reg [31:0] rd_value;
  always @* begin
    rd_value = 32'h0000_0000;
    if (rd_mapped) begin
      case (s_axil_araddr[3:2])
        IDX_CTRL:   rd_value = {29'd0, mode, ie, en};
        IDX_LOAD:   rd_value = load;
        IDX_COUNT:  rd_value = count;
        IDX_STATUS: rd_value = {31'd0, expired};
        default:    rd_value = 32'h0000_0000;
      endcase
    end
  end

  // ---------------------------------------------------------------------
  // Timer end of count: EN is 1 and COUNT is 1 or 0
  // ---------------------------------------------------------------------
  wire count_end = en && (count[31:1] == 31'd0);

  // ---------------------------------------------------------------------
  // Channel registers
  // ---------------------------------------------------------------------
  always @(posedge aclk) begin
    if (!aresetn) begin
      aw_held       <= 1'b0;
      w_held        <= 1'b0;
      aw_addr_q     <= {ADDR_WIDTH{1'b0}};
      w_data_q      <= 32'h0000_0000;
      w_strb_q      <= 4'h0;
      s_axil_bvalid <= 1'b0;
      s_axil_bresp  <= RESP_OKAY;
      s_axil_rvalid <= 1'b0;
      s_axil_rdata  <= 32'h0000_0000;
      s_axil_rresp  <= RESP_OKAY;
    end else begin
      if (s_axil_bvalid && s_axil_bready) begin
        s_axil_bvalid <= 1'b0;
      end
      if (do_write) begin
        aw_held       <= 1'b0;
        w_held        <= 1'b0;
        s_axil_bvalid <= 1'b1;
        s_axil_bresp  <= wr_okay ? RESP_OKAY : RESP_SLVERR;
      end else begin
        if (aw_hs) begin
          aw_held   <= 1'b1;
          aw_addr_q <= s_axil_awaddr;
        end
        if (w_hs) begin
          w_held   <= 1'b1;
          w_data_q <= s_axil_wdata;
          w_strb_q <= s_axil_wstrb;
        end
      end

      if (s_axil_rvalid && s_axil_rready) begin
        s_axil_rvalid <= 1'b0;
      end
      if (ar_hs) begin
        s_axil_rvalid <= 1'b1;
        s_axil_rdata  <= rd_value;
        s_axil_rresp  <= rd_mapped ? RESP_OKAY : RESP_SLVERR;
      end
    end
  end

  // ---------------------------------------------------------------------
  // Timer registers. Order gives the spec's priorities (last wins):
  //   1. count step, 2. expired clear then set, 3. CTRL write, 4. LOAD write
  // ---------------------------------------------------------------------
  always @(posedge aclk) begin
    if (!aresetn) begin
      en      <= 1'b0;
      ie      <= 1'b0;
      mode    <= 1'b0;
      expired <= 1'b0;
      load    <= 32'h0000_0000;
      count   <= 32'h0000_0000;
    end else begin
      // 1. Count step
      if (en) begin
        if (count_end) begin
          if (mode) begin
            count <= load;
          end else begin
            count <= 32'h0000_0000;
            en    <= 1'b0;
          end
        end else begin
          count <= count - 32'd1;
        end
      end

      // 2. Expiry: a count end beats a clear
      if (wr_clear) begin
        expired <= 1'b0;
      end
      if (count_end) begin
        expired <= 1'b1;
      end

      // 3. CTRL write wins for en and count
      if (wr_ctrl) begin
        en   <= wr_data[0];
        ie   <= wr_data[1];
        mode <= wr_data[2];
        if (wr_data[0]) begin
          count <= load;
        end
      end

      // 4. LOAD byte merge
      if (wr_load) begin
        if (wr_strb[0]) load[7:0]   <= wr_data[7:0];
        if (wr_strb[1]) load[15:8]  <= wr_data[15:8];
        if (wr_strb[2]) load[23:16] <= wr_data[23:16];
        if (wr_strb[3]) load[31:24] <= wr_data[31:24];
      end
    end
  end

  assign irq = expired && ie;

endmodule
=== END FILE ===
=== FILE: axil_timer_tb.v ===
// axil_timer_tb: directed self-checking testbench for axil_timer.
// Drives an ADDR_WIDTH 8 instance (dut8) and an ADDR_WIDTH 4 instance (dut4)
// with the same stimulus and checks they agree; offsets from 0x10 up are sent
// to dut8 only. Every failed check reports with $error.

`define CHECK(cond, msg) \
  begin \
    if (cond) passed = passed + 1; \
    else begin \
      failed = failed + 1; \
      $error("check failed at edge %0d: %0s", cyc, msg); \
    end \
  end

`define CHECK_EQ(got, exp, msg) \
  begin \
    if ((got) === (exp)) passed = passed + 1; \
    else begin \
      failed = failed + 1; \
      $error("check failed at edge %0d: %0s: got 0x%0h expected 0x%0h", cyc, msg, got, exp); \
    end \
  end

module axil_timer_tb;

  localparam [7:0] A_CTRL   = 8'h00;
  localparam [7:0] A_LOAD   = 8'h04;
  localparam [7:0] A_COUNT  = 8'h08;
  localparam [7:0] A_STATUS = 8'h0C;
  localparam [1:0] OKAY     = 2'b00;
  localparam [1:0] SLVERR   = 2'b10;

  reg        clk = 1'b0;
  reg        aresetn;
  reg [7:0]  awaddr;
  reg        awvalid;
  reg [31:0] wdata;
  reg [3:0]  wstrb;
  reg        wvalid;
  reg        bready;
  reg [7:0]  araddr;
  reg        arvalid;
  reg        rready;
  reg        lane4;
  reg        lock_on;

  wire        awready, wready, bvalid, arready, rvalid, irq;
  wire [1:0]  bresp, rresp;
  wire [31:0] rdata;

  wire        awready4, wready4, bvalid4, arready4, rvalid4, irq4;
  wire [1:0]  bresp4, rresp4;
  wire [31:0] rdata4;

  wire awvalid4 = awvalid & lane4;
  wire wvalid4  = wvalid & lane4;
  wire arvalid4 = arvalid & lane4;

  axil_timer #(.ADDR_WIDTH(8)) dut8 (
    .aclk(clk), .aresetn(aresetn),
    .s_axil_awaddr(awaddr), .s_axil_awvalid(awvalid), .s_axil_awready(awready),
    .s_axil_wdata(wdata), .s_axil_wstrb(wstrb), .s_axil_wvalid(wvalid), .s_axil_wready(wready),
    .s_axil_bresp(bresp), .s_axil_bvalid(bvalid), .s_axil_bready(bready),
    .s_axil_araddr(araddr), .s_axil_arvalid(arvalid), .s_axil_arready(arready),
    .s_axil_rdata(rdata), .s_axil_rresp(rresp), .s_axil_rvalid(rvalid), .s_axil_rready(rready),
    .irq(irq)
  );

  axil_timer #(.ADDR_WIDTH(4)) dut4 (
    .aclk(clk), .aresetn(aresetn),
    .s_axil_awaddr(awaddr[3:0]), .s_axil_awvalid(awvalid4), .s_axil_awready(awready4),
    .s_axil_wdata(wdata), .s_axil_wstrb(wstrb), .s_axil_wvalid(wvalid4), .s_axil_wready(wready4),
    .s_axil_bresp(bresp4), .s_axil_bvalid(bvalid4), .s_axil_bready(bready),
    .s_axil_araddr(araddr[3:0]), .s_axil_arvalid(arvalid4), .s_axil_arready(arready4),
    .s_axil_rdata(rdata4), .s_axil_rresp(rresp4), .s_axil_rvalid(rvalid4), .s_axil_rready(rready),
    .irq(irq4)
  );

  always #5 clk = ~clk;

  // Edge counter: cyc is the number of rising edges so far.
  integer cyc = 0;
  always @(posedge clk) cyc = cyc + 1;

  // irq rise monitor: last_rise is the edge after which irq rose.
  integer n_rise    = 0;
  integer last_rise = 0;
  reg     irq_prev  = 1'b0;
  always @(negedge clk) begin
    if (irq === 1'b1 && irq_prev === 1'b0) begin
      n_rise    = n_rise + 1;
      last_rise = cyc;
    end
    irq_prev = irq;
  end

  // Lockstep monitor between the two address widths.
  integer lock_err = 0;
  always @(negedge clk) begin
    if (lock_on && lane4) begin
      if ((awready4 !== awready) || (wready4 !== wready) || (bvalid4 !== bvalid) ||
          (arready4 !== arready) || (rvalid4 !== rvalid) || (irq4 !== irq) ||
          (bvalid && (bresp4 !== bresp)) ||
          (rvalid && ((rresp4 !== rresp) || (rdata4 !== rdata)))) begin
        lock_err = lock_err + 1;
        if (lock_err <= 5)
          $error("ADDR_WIDTH 4 and 8 instances disagree at edge %0d", cyc);
      end
    end
  end

  integer passed, failed;
  integer wr_edge, rd_edge;
  reg [1:0]  wr_resp, rd_resp;
  reg [31:0] rd_data;
  integer t0, N, S, t, n0;
  reg [31:0] exp32;
  reg [8*64-1:0] nonce;

  task tick;
    begin
      @(posedge clk);
      #1;
    end
  endtask

  task wait_until;
    input integer target;
    begin
      while (cyc < target) tick;
    end
  endtask

  task wait_rise;
    input integer n_before;
    input integer timeout;
    integer g;
    begin
      g = 0;
      while ((n_rise == n_before) && (g < timeout)) begin
        tick;
        g = g + 1;
      end
      `CHECK(n_rise != n_before, "irq rose within the timeout")
    end
  endtask

  // order: 0 AW and W together, 1 AW first, 2 W first
  task axi_write;
    input [7:0]  a;
    input [31:0] d;
    input [3:0]  s;
    input integer order;
    input integer bdelay;
    reg hs_aw, hs_w, aw_done, w_done;
    reg [1:0] resp_q;
    integer g, k;
    begin
      `CHECK(bvalid == 1'b0, "BVALID low before a write")
      awaddr  = a;
      wdata   = d;
      wstrb   = s;
      awvalid = (order != 2);
      wvalid  = (order != 1);
      aw_done = 1'b0;
      w_done  = 1'b0;
      g = 0;
      while (!(aw_done && w_done) && (g < 50)) begin
        hs_aw = awvalid && awready;
        hs_w  = wvalid && wready;
        tick;
        g = g + 1;
        if (hs_aw) begin
          aw_done = 1'b1;
          awvalid = 1'b0;
          awaddr  = 8'hEE;
        end
        if (hs_w) begin
          w_done = 1'b1;
          wvalid = 1'b0;
          wdata  = 32'hDEAD_BEEF;
          wstrb  = 4'hF;
        end
        if (!(aw_done && w_done)) begin
          `CHECK(bvalid == 1'b0, "no B before both halves of the write")
          if (aw_done) begin
            `CHECK(awready == 1'b0, "AWREADY low while an address is held")
            wvalid = 1'b1;
          end
          if (w_done) begin
            `CHECK(wready == 1'b0, "WREADY low while data is held")
            awvalid = 1'b1;
          end
        end
      end
      `CHECK(aw_done && w_done, "write handshakes complete")
      wr_edge = cyc;
      `CHECK(bvalid == 1'b1, "BVALID rises on the edge the write completes")
      resp_q = bresp;
      for (k = 0; k < bdelay; k = k + 1) begin
        tick;
        `CHECK((bvalid == 1'b1) && (bresp == resp_q), "B held stable under backpressure")
        `CHECK((awready == 1'b0) && (wready == 1'b0), "no write accepted while B waits")
      end
      bready = 1'b1;
      tick;
      bready = 1'b0;
      `CHECK(bvalid == 1'b0, "BVALID drops after the B handshake")
      wr_resp = resp_q;
    end
  endtask

  task axi_read;
    input [7:0] a;
    input integer rdelay;
    reg hs;
    reg [31:0] d_q;
    reg [1:0]  r_q;
    integer g, k;
    begin
      `CHECK(rvalid == 1'b0, "RVALID low before a read")
      araddr  = a;
      arvalid = 1'b1;
      hs = 1'b0;
      g = 0;
      while (!hs && (g < 50)) begin
        hs = arvalid && arready;
        tick;
        g = g + 1;
      end
      arvalid = 1'b0;
      araddr  = 8'hEE;
      `CHECK(hs, "read address accepted")
      rd_edge = cyc;
      `CHECK(rvalid == 1'b1, "RVALID rises on the edge after AR")
      d_q = rdata;
      r_q = rresp;
      for (k = 0; k < rdelay; k = k + 1) begin
        tick;
        `CHECK((rvalid == 1'b1) && (rdata == d_q) && (rresp == r_q), "R held stable under backpressure")
        `CHECK(arready == 1'b0, "no read accepted while R waits")
      end
      rready = 1'b1;
      tick;
      rready = 1'b0;
      `CHECK(rvalid == 1'b0, "RVALID drops after the R handshake")
      rd_data = d_q;
      rd_resp = r_q;
    end
  endtask

  task wr_ok;
    input [7:0]  a;
    input [31:0] d;
    begin
      axi_write(a, d, 4'hF, 0, 0);
      if (wr_resp === OKAY) passed = passed + 1;
      else begin
        failed = failed + 1;
        $error("write of 0x%h to 0x%h at edge %0d: response %b expected OKAY", d, a, cyc, wr_resp);
      end
    end
  endtask

  task rd_expect;
    input [7:0]  a;
    input [31:0] exp_d;
    input [1:0]  exp_r;
    begin
      axi_read(a, 0);
      if ((rd_data === exp_d) && (rd_resp === exp_r)) passed = passed + 1;
      else begin
        failed = failed + 1;
        $error("read of 0x%h at edge %0d: got 0x%h/%b expected 0x%h/%b",
               a, cyc, rd_data, rd_resp, exp_d, exp_r);
      end
    end
  endtask

  task oneshot_timed;
    input [31:0] ld;
    input integer len;
    begin
      wr_ok(A_LOAD, ld);
      n0 = n_rise;
      wr_ok(A_CTRL, 32'h3);          // EN | IE, one-shot
      t0 = wr_edge;
      if (len >= 20) begin
        axi_read(A_COUNT, 1);
        exp32 = len - (rd_edge - 1 - t0);
        `CHECK_EQ(rd_data, exp32, "COUNT read mid-count")
      end
      wait_rise(n0, len + 50);
      `CHECK_EQ(last_rise, t0 + len, "one-shot count ends LOAD edges after the start")
      `CHECK_EQ(n_rise, n0 + 1, "one interrupt per one-shot count")
      rd_expect(A_CTRL, 32'h2, OKAY);   // EN cleared itself, IE kept
      rd_expect(A_COUNT, 32'h0, OKAY);
      rd_expect(A_STATUS, 32'h1, OKAY);
      `CHECK(irq == 1'b1, "irq holds until the expiry is cleared")
      wr_ok(A_STATUS, 32'h1);
      `CHECK(irq == 1'b0, "STATUS clear drops irq")
      n0 = n_rise;
      repeat (len + 10) tick;
      `CHECK_EQ(n_rise, n0, "no second interrupt after a one-shot")
      `CHECK(irq == 1'b0, "irq stays low after a one-shot")
      rd_expect(A_STATUS, 32'h0, OKAY);
      rd_expect(A_COUNT, 32'h0, OKAY);
    end
  endtask

  // Watchdog
  initial begin
    #300000;
    $error("watchdog: simulation did not finish");
    $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed + 1);
    $finish;
  end

  initial begin
    nonce = {64{8'h00}};
    if (!$value$plusargs("nirmaan_nonce=%s", nonce))
      $display("note: no nirmaan_nonce plusarg given");
    passed  = 0;
    failed  = 0;
    lock_on = 1'b0;
    lane4   = 1'b1;
    aresetn = 1'b0;
    awaddr  = 8'h00; awvalid = 1'b0;
    wdata   = 32'h0; wstrb = 4'h0; wvalid = 1'b0;
    bready  = 1'b0;
    araddr  = 8'h00; arvalid = 1'b0;
    rready  = 1'b0;
    repeat (3) tick;
    aresetn = 1'b1;
    lock_on = 1'b1;

    // ---------------- Reset values ----------------
    `CHECK((awready == 1'b1) && (wready == 1'b1) && (arready == 1'b1), "READY high after reset")
    `CHECK((bvalid == 1'b0) && (rvalid == 1'b0), "VALID low after reset")
    `CHECK(irq == 1'b0, "irq low after reset")
    rd_expect(A_CTRL,   32'h0, OKAY);
    rd_expect(A_LOAD,   32'h0, OKAY);
    rd_expect(A_COUNT,  32'h0, OKAY);
    rd_expect(A_STATUS, 32'h0, OKAY);

    // ---------------- LOAD with partial strobes, both orders, backpressure ----------------
    axi_write(A_LOAD, 32'hFFFF_FFFF, 4'hF, 1, 2);
    `CHECK_EQ(wr_resp, OKAY, "LOAD write AW first")
    rd_expect(A_LOAD, 32'hFFFF_FFFF, OKAY);
    axi_write(A_LOAD, 32'h1234_5678, 4'h1, 2, 0);
    `CHECK_EQ(wr_resp, OKAY, "LOAD write W first")
    rd_expect(A_LOAD, 32'hFFFF_FF78, OKAY);
    axi_write(A_LOAD, 32'hAABB_CCDD, 4'h6, 0, 3);
    `CHECK_EQ(wr_resp, OKAY, "LOAD write middle bytes")
    rd_expect(A_LOAD, 32'hFFBB_CC78, OKAY);
    axi_write(A_LOAD, 32'h1100_0000, 4'h8, 1, 0);
    `CHECK_EQ(wr_resp, OKAY, "LOAD write top byte")
    rd_expect(A_LOAD, 32'h11BB_CC78, OKAY);
    axi_write(A_LOAD, 32'h0000_0000, 4'h0, 2, 1);
    `CHECK_EQ(wr_resp, OKAY, "LOAD write with no strobes answers OKAY")
    rd_expect(A_LOAD, 32'h11BB_CC78, OKAY);
    axi_read(A_LOAD, 4);
    `CHECK_EQ(rd_data, 32'h11BB_CC78, "LOAD read under R backpressure")

    // ---------------- COUNT read only, SLVERR policy ----------------
    axi_write(A_COUNT, 32'h0000_0055, 4'hF, 0, 0);
    `CHECK_EQ(wr_resp, SLVERR, "COUNT write gets SLVERR")
    rd_expect(A_COUNT, 32'h0, OKAY);
    axi_write(8'h05, 32'h0000_0000, 4'hF, 1, 0);
    `CHECK_EQ(wr_resp, SLVERR, "unaligned write gets SLVERR")
    rd_expect(A_LOAD, 32'h11BB_CC78, OKAY);
    axi_write(8'h01, 32'h0000_0007, 4'hF, 0, 0);
    `CHECK_EQ(wr_resp, SLVERR, "unaligned CTRL write gets SLVERR")
    rd_expect(A_CTRL, 32'h0, OKAY);
    rd_expect(8'h02, 32'h0, SLVERR);
    rd_expect(8'h07, 32'h0, SLVERR);
    // Offsets from 0x10 up: ADDR_WIDTH 8 instance only
    lane4 = 1'b0;
    axi_write(8'h10, 32'h0000_0007, 4'hF, 0, 0);
    `CHECK_EQ(wr_resp, SLVERR, "write to 0x10 gets SLVERR")
    axi_write(8'h14, 32'h0000_0000, 4'hF, 2, 0);
    `CHECK_EQ(wr_resp, SLVERR, "write to 0x14 gets SLVERR")
    axi_write(8'hFC, 32'h0000_0001, 4'hF, 0, 0);
    `CHECK_EQ(wr_resp, SLVERR, "write to 0xFC gets SLVERR")
    rd_expect(8'h14, 32'h0, SLVERR);
    rd_expect(8'h84, 32'h0, SLVERR);
    rd_expect(8'h10, 32'h0, SLVERR);
    rd_expect(8'hF8, 32'h0, SLVERR);
    lane4 = 1'b1;
    rd_expect(A_CTRL,   32'h0, OKAY);
    rd_expect(A_LOAD,   32'h11BB_CC78, OKAY);
    rd_expect(A_STATUS, 32'h0, OKAY);
    `CHECK(irq == 1'b0, "no aliasing write reached CTRL")

    // ---------------- CTRL write without wstrb[0] ----------------
    axi_write(A_CTRL, 32'h0000_0007, 4'hE, 0, 0);
    `CHECK_EQ(wr_resp, OKAY, "CTRL write without wstrb0 answers OKAY")
    rd_expect(A_CTRL,  32'h0, OKAY);
    rd_expect(A_COUNT, 32'h0, OKAY);
    repeat (5) tick;
    `CHECK(irq == 1'b0, "CTRL write without wstrb0 starts nothing")
    rd_expect(A_STATUS, 32'h0, OKAY);

    // ---------------- One-shot counts timed to the cycle ----------------
    oneshot_timed(32'd5, 5);
    oneshot_timed(32'd1, 1);
    oneshot_timed(32'd0, 1);
    oneshot_timed(32'd37, 37);

    // ---------------- Interrupt enable on a pending expiry ----------------
    wr_ok(A_LOAD, 32'd4);
    n0 = n_rise;
    wr_ok(A_CTRL, 32'h1);            // EN, IE 0
    t0 = wr_edge;
    wait_until(t0 + 10);
    `CHECK(irq == 1'b0, "masked expiry keeps irq low")
    `CHECK_EQ(n_rise, n0, "no irq rise while IE is 0")
    rd_expect(A_STATUS, 32'h1, OKAY);
    rd_expect(A_CTRL,   32'h0, OKAY);
    axi_write(A_STATUS, 32'h0000_0001, 4'hE, 0, 0);
    `CHECK_EQ(wr_resp, OKAY, "STATUS write without wstrb0 answers OKAY")
    rd_expect(A_STATUS, 32'h1, OKAY);
    wr_ok(A_STATUS, 32'h0);
    rd_expect(A_STATUS, 32'h1, OKAY);
    n0 = n_rise;
    wr_ok(A_CTRL, 32'h2);            // IE 1, EXPIRED pending
    `CHECK_EQ(n_rise, n0 + 1, "irq rises when IE is written 1 on a pending expiry")
    `CHECK_EQ(last_rise, wr_edge, "irq rises on the edge the IE write takes effect")
    `CHECK(irq == 1'b1, "irq high with IE and EXPIRED")
    wr_ok(A_CTRL, 32'h0);
    `CHECK(irq == 1'b0, "IE written 0 masks irq")
    rd_expect(A_STATUS, 32'h1, OKAY);
    wr_ok(A_CTRL, 32'h2);
    `CHECK(irq == 1'b1, "IE written 1 again raises irq")
    wr_ok(A_STATUS, 32'h1);
    `CHECK(irq == 1'b0, "STATUS clear drops irq")
    rd_expect(A_STATUS, 32'h0, OKAY);

    // ---------------- Periodic counts timed over several periods ----------------
    N = 12;
    wr_ok(A_LOAD, N);
    n0 = n_rise;
    wr_ok(A_CTRL, 32'h7);            // EN | IE | MODE
    t0 = wr_edge;
    wait_rise(n0, 60);
    `CHECK_EQ(last_rise, t0 + N, "periodic first count ends LOAD edges after start")
    wr_ok(A_STATUS, 32'h1);
    `CHECK(irq == 1'b0, "periodic expiry cleared")
    n0 = n_rise;
    axi_read(A_COUNT, 0);
    t = rd_edge - 1 - t0;
    exp32 = N - (t % N);
    `CHECK_EQ(rd_data, exp32, "COUNT within a period")
    wait_rise(n0, 60);
    `CHECK_EQ(last_rise, t0 + 2 * N, "periodic second end")
    rd_expect(A_CTRL, 32'h7, OKAY);
    // Acknowledge on the very edge the third count ends: the expiry is kept.
    wait_until(t0 + 3 * N - 1);
    axi_write(A_STATUS, 32'h0000_0001, 4'h1, 0, 0);
    `CHECK_EQ(wr_edge, t0 + 3 * N, "STATUS clear lands on the end edge")
    `CHECK(irq == 1'b1, "a count end beats a clear")
    rd_expect(A_STATUS, 32'h1, OKAY);
    n0 = n_rise;
    wr_ok(A_STATUS, 32'h1);
    `CHECK(irq == 1'b0, "clear after the kept expiry")
    wait_rise(n0, 60);
    `CHECK_EQ(last_rise, t0 + 4 * N, "periodic fourth end")
    n0 = n_rise;
    wr_ok(A_STATUS, 32'h1);
    wait_rise(n0, 60);
    `CHECK_EQ(last_rise, t0 + 5 * N, "periodic fifth end")
    wr_ok(A_STATUS, 32'h1);

    // ---------------- Stop freezes COUNT ----------------
    t = cyc + 5;
    wait_until(t);
    n0 = n_rise;
    wr_ok(A_CTRL, 32'h6);            // EN 0, IE 1, MODE 1
    S = wr_edge;
    exp32 = N - ((S - t0) % N);
    axi_read(A_COUNT, 0);
    `CHECK_EQ(rd_data, exp32, "COUNT frozen at the stop")
    repeat (3 * N) tick;
    rd_expect(A_COUNT, exp32, OKAY);
    rd_expect(A_CTRL, 32'h6, OKAY);
    `CHECK_EQ(n_rise, n0, "no count ends while stopped")
    rd_expect(A_STATUS, 32'h0, OKAY);

    // ---------------- Restart mid-count ----------------
    wr_ok(A_LOAD, 32'd20);
    n0 = n_rise;
    wr_ok(A_CTRL, 32'h3);
    t0 = wr_edge;
    wait_until(t0 + 8);
    wr_ok(A_CTRL, 32'h3);
    S = wr_edge;
    wait_rise(n0, 80);
    `CHECK_EQ(last_rise, S + 20, "restart counts from LOAD again")
    rd_expect(A_CTRL, 32'h2, OKAY);
    wr_ok(A_STATUS, 32'h1);

    // ---------------- Restart on the end edge ----------------
    wr_ok(A_LOAD, 32'd10);
    n0 = n_rise;
    wr_ok(A_CTRL, 32'h3);
    t0 = wr_edge;
    wait_until(t0 + 9);
    axi_write(A_CTRL, 32'h0000_0003, 4'h1, 0, 0);
    `CHECK_EQ(wr_resp, OKAY, "CTRL restart answers OKAY")
    `CHECK_EQ(wr_edge, t0 + 10, "CTRL restart lands on the end edge")
    `CHECK_EQ(n_rise, n0 + 1, "the count that ended still sets EXPIRED")
    `CHECK_EQ(last_rise, t0 + 10, "expiry on the end edge")
    rd_expect(A_CTRL, 32'h3, OKAY);
    n0 = n_rise;
    wr_ok(A_STATUS, 32'h1);
    `CHECK(irq == 1'b0, "cleared after end-edge restart")
    wait_rise(n0, 40);
    `CHECK_EQ(last_rise, t0 + 20, "end-edge restart counts LOAD edges again")
    rd_expect(A_CTRL, 32'h2, OKAY);
    wr_ok(A_STATUS, 32'h1);

    // ---------------- Read and write on the same edge ----------------
    wr_ok(A_LOAD, 32'hA5A5_A5A5);
    awaddr = A_LOAD; wdata = 32'h5A5A_5A5A; wstrb = 4'hF;
    awvalid = 1'b1; wvalid = 1'b1;
    araddr = A_LOAD; arvalid = 1'b1;
    `CHECK(awready && wready && arready, "all READY high when idle")
    tick;
    awvalid = 1'b0; wvalid = 1'b0; arvalid = 1'b0;
    `CHECK(bvalid && rvalid, "B and R after a same-edge write and read")
    `CHECK_EQ(rdata, 32'hA5A5_A5A5, "read on the write edge returns the old value")
    `CHECK_EQ(bresp, OKAY, "same-edge write OKAY")
    `CHECK_EQ(rresp, OKAY, "same-edge read OKAY")
    bready = 1'b1; rready = 1'b1;
    tick;
    bready = 1'b0; rready = 1'b0;
    `CHECK(!bvalid && !rvalid, "B and R complete")
    rd_expect(A_LOAD, 32'h5A5A_5A5A, OKAY);

    // ---------------- Reset during a count, with a held write address ----------------
    wr_ok(A_LOAD, 32'd30);
    wr_ok(A_CTRL, 32'h7);
    t0 = wr_edge;
    wait_until(t0 + 10);
    awaddr = A_LOAD; awvalid = 1'b1;
    tick;
    awvalid = 1'b0;
    `CHECK(awready == 1'b0, "write address held before reset")
    aresetn = 1'b0;
    tick;
    tick;
    aresetn = 1'b1;
    `CHECK((awready == 1'b1) && (wready == 1'b1) && (arready == 1'b1), "READY high after reset in traffic")
    `CHECK((bvalid == 1'b0) && (rvalid == 1'b0), "VALID low after reset in traffic")
    `CHECK(irq == 1'b0, "irq low after reset in traffic")
    n0 = n_rise;
    rd_expect(A_CTRL,   32'h0, OKAY);
    rd_expect(A_LOAD,   32'h0, OKAY);
    rd_expect(A_COUNT,  32'h0, OKAY);
    rd_expect(A_STATUS, 32'h0, OKAY);
    // W alone must not complete a write: the held address was cleared
    wdata = 32'h0000_00AB; wstrb = 4'hF; wvalid = 1'b1;
    `CHECK(wready == 1'b1, "WREADY high after reset")
    tick;
    wvalid = 1'b0;
    `CHECK(wready == 1'b0, "W held")
    `CHECK(bvalid == 1'b0, "no B from W alone after reset")
    tick;
    tick;
    `CHECK(bvalid == 1'b0, "still no B from W alone")
    awaddr = A_LOAD; awvalid = 1'b1;
    `CHECK(awready == 1'b1, "AWREADY high with W held")
    tick;
    awvalid = 1'b0;
    `CHECK(bvalid == 1'b1, "B after the address joins held data")
    `CHECK_EQ(bresp, OKAY, "W-first write after reset OKAY")
    bready = 1'b1;
    tick;
    bready = 1'b0;
    `CHECK(bvalid == 1'b0, "B complete")
    rd_expect(A_LOAD, 32'h0000_00AB, OKAY);
    repeat (40) tick;
    `CHECK_EQ(n_rise, n0, "no interrupt after reset during a count")
    rd_expect(A_COUNT, 32'h0, OKAY);
    rd_expect(A_CTRL,  32'h0, OKAY);

    // ---------------- Verdict ----------------
    if (lock_err == 0) passed = passed + 1;
    else failed = failed + lock_err;
    $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
    $finish;
  end

endmodule
